mapper.select:
SELECT 1 AS report_type, DATE_FORMAT(r.create_time, '%Y-%m') AS statistic_period, CONCAT('REPORT', DATE_FORMAT(NOW(), '%Y%m'), r.ent_id) AS report_no, r.ent_id, e.ent_name, '低风险' AS risk_level, e.area_name AS area, e.ent_type_name AS ent_type, MIN(r.create_time) AS begin_time, MAX(r.create_time) AS end_time, COUNT(r.id) AS violation_count
FROM rectify_review r LEFT JOIN enterprise_info e ON r.ent_id = e.id WHERE r.deleted = 0 AND e.deleted = 0
AND DATE_FORMAT(r.create_time, '%Y-%m') = #{statisticPeriod}
AND e.area_name = #{area}
AND e.ent_type_name = #{entType}
AND r.create_time >= #{beginTime}
AND r.create_time <= #{endTime}
AND e.ent_name LIKE CONCAT('%', #{entName}, '%')
GROUP BY r.ent_id, DATE_FORMAT(r.create_time, '%Y-%m')
ORDER BY r.ent_id DESC
LIMIT #{pageSize} OFFSET ${(pageNo - 1) * pageSize}

SELECT COUNT(*) FROM (
                         SELECT 1
                         FROM rectify_review r
                                  LEFT JOIN enterprise_info e ON r.ent_id = e.id
                         WHERE r.deleted = 0
                           AND e.deleted = 0


                            AND DATE_FORMAT(r.create_time, '%Y-%m') = #{statisticPeriod}


                            AND e.area_name = #{area}


                            AND e.ent_type_name = #{entType}


                            AND r.create_time >= #{beginTime}


                            AND r.create_time <= #{endTime}


                            AND e.ent_name LIKE CONCAT('%', #{entName}, '%')

                         GROUP BY r.ent_id, DATE_FORMAT(r.create_time, '%Y-%m')
                     ) AS temp
